/** 文件工具 **/
import { readFileSync, readdirSync, statSync } from "node:fs";
import { extname, isAbsolute, join, normalize, sep } from "node:path";
import { cwd } from "node:process";
import Yaml from "yaml";

/**
 * @name 绝对路径
 * @param {string} [path=""] 路径
 * @param {string} [dir=cwd()] 上下文
 */
function absPath(path = "", dir: string = cwd()): string {
	return join(dir, path);
}

/**
 * @name 读取文件路径
 * @param {string} [dir=""] 路径
 * @param {string} [path=""] 路径
 * @param {regexp} [regexp=/(node_modules|\.git|\.DS_Store)$/] 过滤正则
 * @param {string} [type="bfs"] 类型：bfs、dfs
 */
function readDir({
	dir = cwd(),
	path,
	regexp = /node_modules|\.git$|\.DS_Store$/,
	type = "bfs"
}: {
	dir?: string
	path: string
	regexp?: RegExp
	type?: "bfs" | "dfs"
}): string[] {
	const finalPath = absPath(path, dir);
	if (type === "bfs") {
		const paths: string[] = [];
		const queue: string[] = [];
		if (!regexp.test(finalPath)) queue.push(finalPath);
		let head = 0;
		while (head < queue.length) {
			const topPath = queue[head++];
			const stat = statSync(topPath);
			if (!regexp.test(topPath)) {
				if (stat.isDirectory()) {
					const subPaths = readdirSync(topPath).map(v => join(topPath, v));
					queue.push(...subPaths);
				} else if (stat.isFile()) {
					paths.push(topPath);
				}
			}
		}
		return paths;
	} else {
		const paths: string[] = [];
		const stat = statSync(finalPath);
		if (!regexp.test(finalPath)) {
			if (stat.isDirectory()) {
				const subPaths = readdirSync(finalPath).map(v => join(finalPath, v));
				subPaths.forEach(v => {
					const dfsPaths = readDir({
						dir: "",
						path: v,
						regexp,
						type: "dfs"
					});
					paths.push(...dfsPaths);
				});
			} else if (stat.isFile()) {
				paths.push(finalPath);
			}
		}
		return paths;
	}
}

/**
 * @name 读取YAML文件
 * @param {string} [path=""] 路径
 * @param {string} [dir=cwd()] 上下文
 */
function readYaml<T>(path = "", dir: string = cwd()): T | null {
	const finalPath = absPath(path, dir);
	const ext = extname(finalPath);
	if (!/^\.ya?ml$/.test(ext)) return null;
	const text = readFileSync(finalPath, "utf8");
	return Yaml.parse(text) as T;
}

/**
 * @name 验证路径
 * @param {string} [path=""] 路径
 * @param {string} [dir=cwd()] 上下文
 */
function verifyPath(path = "", dir: string = cwd()): {
	flag: boolean
	msg: string
} {
	const finalPath = absPath(path, dir);
	if (!isAbsolute(finalPath)) {
		return { flag: false, msg: "non absolute path" };
	}
	const names = finalPath.split(sep);
	const filteredNames = names.filter(Boolean);
	if (names.includes("")) {
		return { flag: false, msg: "con separator path" };
	}
	if (filteredNames.length === 0) {
		return { flag: false, msg: "empty path" };
	}
	if (filteredNames.some(v => /[\\/:*?"|<>]/.test(v))) {
		return { flag: false, msg: "illegal string path" };
	}
	if (finalPath !== normalize(finalPath)) {
		return { flag: false, msg: "non standard path" };
	}
	return { flag: true, msg: "" };
}

export {
	absPath,
	readDir,
	readYaml,
	verifyPath
};