/** 类型工具 **/

/**
 * @name Web类型
 * @param {string} [ua=""] 用户代理
 */
type EngineEnum = "webkit" | "gecko" | "presto" | "trident";

type PlatformEnum = "desktop" | "mobile";

type ShellEnum = "uc" | "qq" | "sougou" | "maxthon" | "2345" | "360" | "liebao" | "xiaomi" | "huawei" | "oppo" | "vivo" | "wechat" | "baidu" | "toutiao";

type SupporterEnum = "chrome" | "safari" | "edge" | "firefox" | "opera" | "iexplore";

type SystemEnum = "windows" | "macos" | "linux" | "android" | "ios";

type EngineType = Record<EngineEnum, RegExp[]>;

type ShellType = Record<ShellEnum, RegExp[]>;

type SupporterType = Record<SupporterEnum, RegExp[]>;

type SystemType = Record<SystemEnum, RegExp>;

type SystemVsType = Record<string, RegExp>;

export interface WebType {
	engine: EngineEnum | "unknow"
	engineVs: string
	platform: PlatformEnum
	shell?: ShellEnum | "none"
	shellVs?: string
	supporter: SupporterEnum | "unknow"
	supporterVs: string
	system: SystemEnum | "unknow"
	systemVs: string
}

function webType(ua = ""): WebType {
	// 权重：系统 > 平台 > 内核 > 载体 > 外壳
	const finalUa = ua.toLowerCase();
	const testUa = (regexp: RegExp): boolean => regexp.test(finalUa);
	const testVs = (regexp: RegExp): string => (finalUa.match(regexp) ?? "").toString().replace(/[^0-9|_.]/g, "")
		.replace(/_/g, ".") || "unknow";
	/* eslint-disable sort-properties/sort-object-expression */
	// 系统
	const systemMap: SystemType = {
		windows: /windows|win32|win64|wow32|wow64/g,
		macos: /macintosh|macintel/g,
		linux: /x11|ubuntu/g,
		android: /android|adr/g,
		ios: /ios|iphone|ipad|ipod/g
	};
	const systemVsMap: SystemVsType = {
		macos: /mac os x [\d._]+/g,
		linux: /ubuntu\/[\d._]+/g,
		android: /android [\d._]+/g,
		ios: /os [\d._]+/g
	};
	const systemVsByWin = (): string => {
		const vs = (finalUa.match(/(windows nt [\d._]+)|(windows [\w._]+)/g) ?? "")
			.toString()
			.replace(/windows( nt)? /g, "");
		const map: SystemVsType = {
			2000: /^(5\.0|2000)/g,
			xp: /^(5\.1|xp)/g,
			2003: /^(5\.2|2003)/g,
			vista: /^(6\.0|vista)/g,
			7: /^(6\.1|7)/g,
			8: /^(6\.2|8)/g,
			8.1: /^(6\.3|8\.1)/g,
			10: /^(10\.0|10)/g
		};
		return Object.keys(map).find(v => map[v].test(vs)) ?? "unknow";
	};
	const system = (Object.keys(systemMap).find(v => testUa(systemMap[v as SystemEnum])) ?? "unknow") as SystemEnum | "unknow";
	const systemVs = system === "unknow"
		? "unknow version"
		: system === "windows"
			? systemVsByWin()
			: testVs(systemVsMap[system]) || "unknow version";
	// 平台
	const platform: PlatformEnum = testUa(/mobile/g) ? "mobile" : "desktop";
	// 内核
	const engineMap: EngineType = {
		webkit: [/applewebkit/g, /applewebkit\/[\d._]+/g],
		gecko: [/gecko\//g, /rv:[\d._]+/g],
		presto: [/presto/g, /presto\/[\d._]+/g],
		trident: [/compatible|msie|trident/g, /trident\/[\d._]+/g]
	};
	const engine = (Object.keys(engineMap).find(v => testUa(engineMap[v as EngineEnum][0])) ?? "unknow") as EngineEnum | "unknow";
	const engineVs = engine === "unknow"
		? "unknow version"
		: testVs(engineMap[engine][1]) || "unknow version";
	// 载体
	const supporterMap: SupporterType = {
		safari: [/.*safari.*version.*|.*version.*safari.*/g, /version\/[\d._]+/g],
		edge: [/edge?/g, /edge?\/[\d._]+/g],
		firefox: [/firefox/g, /firefox\/[\d._]+/g],
		opera: [/opera|opr/g, /opr\/[\d._]+/g],
		iexplore: [/(msie|trident).*/g, /(msie |rv:)[\d._]+/g],
		chrome: [/chrome/g, /chrome\/[\d._]+/g]
	};
	const supporter = (Object.keys(supporterMap).find(v => testUa(supporterMap[v as SupporterEnum][0])) ?? "unknow") as SupporterEnum | "unknow";
	const supporterVs = supporter === "unknow"
		? "unknow version"
		: testVs(supporterMap[supporter][1]) || "unknow version";
	// 外壳
	const shellMap: ShellType = {
		2345: [/2345explorer/g, /2345explorer\/[\d._]+/g], // 2345 浏览器
		360: [/qihu|360/g, /qihu|360/g], // 360 浏览器(无版本)
		baidu: [/bidubrowser/g, /bidubrowser [\d._]+/g], // 百度浏览器(应用)
		huawei: [/huaweibrowser/g, /huaweibrowser\/[\d._]+/g], // 华为浏览器(内置)
		liebao: [/lbbrowser/g, /lbbrowser/g], // 猎豹浏览器(无版本)
		maxthon: [/maxthon/g, /maxthon\/[\d._]+/g], // 遨游浏览器
		oppo: [/heytapbrowser/g, /heytapbrowser\/[\d._]+/g], // OPPO 浏览器(内置)
		qq: [/qqbrowser/g, /qqbrowser\/[\d._]+/g], // QQ 浏览器
		sougou: [/metasr/g, /metasr/g], // 搜狗浏览器
		toutiao: [/newsarticle/g, /newsarticle\/[\d._]+/g], // 头条浏览器(应用)
		uc: [/ucbrowser/g, /ucbrowser\/[\d._]+/g], // UC 浏览器
		vivo: [/vivobrowser/g, /vivobrowser\/[\d._]+/g], // VIVO 浏览器(内置)
		wechat: [/micromessenger/g, /micromessenger\/[\d._]+/g], // 微信浏览器(应用)
		xiaomi: [/miuibrowser/g, /miuibrowser\/[\d._]+/g] // 小米浏览器(内置)
	};
	const shell = (Object.keys(shellMap).find(v => testUa(shellMap[v as ShellEnum][0])) ?? "none") as ShellEnum | "none";
	const shellVs = shell === "none"
		? "none version"
		: testVs(shellMap[shell][1]) || "none version";
	/* eslint-enable */
	return {
		engine,
		engineVs,
		platform,
		supporter,
		supporterVs,
		system,
		systemVs,
		...shell === "none" ? {} : { shell, shellVs }
	};
}

export {
	webType
};