/** 系统工具 **/
import { createConnection } from "node:net";
import { networkInterfaces } from "node:os";

import { asyncTo } from "../common";

/**
 * @name 自动端口
 * @param {string} [host=本机IP] 域名
 * @param {function} [onCall] 回调函数
 * @param {number} [port=80] 端口
 */
async function autoPort({
	host = getIP(),
	onCall,
	port
}: {
	host?: string
	port: number
	onCall?: (port: number) => void
}): Promise<void> {
	let currentPort = port;
	while (currentPort <= 65535) {
		const res = await checkPort({ host, port: currentPort });
		if (res) {
			onCall?.(currentPort);
			return;
		}
		currentPort++;
	}
	onCall?.(0);
}

/**
 * @name 检查端口
 * @param {string} [host=本机IP] 域名
 * @param {number} [port=80] 端口
 */
async function checkPort({
	host = getIP(),
	port
}: {
	host?: string
	port: number
}): Promise<boolean> {
	const promise = new Promise<boolean>(resolve => {
		if (port < 0 || port > 65535) {
			resolve(false); // 无法使用
			return;
		}
		const server = createConnection({ host, port });
		server.on("connect", () => {
			server.end();
			resolve(false); // 已占用
		});
		server.on("error", () => {
			resolve(true); // 未占用
		});
	});
	const [err, res] = await asyncTo(promise);
	return err ? false : res;
}

/**
 * @name 读取IP
 */
function getIP(): string {
	const ip = "127.0.0.1";
	const obj = networkInterfaces();
	for (const k in obj) {
		const val = obj[k] ?? [];
		for (const v of val) {
			const { address, family, internal } = v;
			if ((family === "IPv4" || (family as unknown) === 4) && address !== ip && !internal) {
				return address;
			}
		}
	}
	return ip;
}

export {
	autoPort,
	checkPort,
	getIP
};