/** 函数工具 **/
type TgtFunc<T, R> = (...args: T[]) => R;

/**
 * @name 异步美化
 * @param {function} [pfn] Promise函数
 */
async function asyncTo<T, U = Error>(pfn: Promise<T>, error?: object): Promise<[U, undefined] | [null, T]> {
	return await pfn
		.then<[null, T]>((data: T) => [null, data])
		.catch<[U, undefined]>((err: U) => [error ? { ...err, ...error } : err, undefined]);
}

/**
 * @name 防抖
 * @param {function} [fn] 函数
 * @param {number} [delay=50] 时延
 * @param {boolean} [immediate=false] 是否立即执行
 */
function debounce<T, R>(fn: TgtFunc<T, R>, delay = 50, immediate = false): TgtFunc<T, R> {
	let timer: ReturnType<typeof setTimeout> | null = null;
	let result: R | undefined = undefined;
	return function(this: object, ...args: T[]): R {
		if (timer) clearTimeout(timer);

		if (immediate) {
			const callNow = !timer;
			timer = setTimeout(() => {
				timer = null;
			}, delay);
			if (callNow) {
				result = fn.apply(this, args);
			}
		} else {
			timer = setTimeout(() => {
				result = fn.apply(this, args);
			}, delay);
		}

		return result as R;
	};
}

/**
 * @name 节流
 * @param {function} [fn] 函数
 * @param {number} [delay=50] 时延
 */
function throttle<T, R>(fn: TgtFunc<T, R>, delay = 50): TgtFunc<T, R> {
	let timer: ReturnType<typeof setTimeout> | null = null;
	let lastTime = 0;
	let result: R | undefined = undefined;
	return function(this: object, ...args: T[]): R {
		const currentTime = Date.now();
		const remainingTime = delay - (currentTime - lastTime);

		if (remainingTime <= 0 || remainingTime > delay) {
			if (timer) {
				clearTimeout(timer);
				timer = null;
			}
			lastTime = currentTime;
			result = fn.apply(this, args);
		} else {
			timer ??= setTimeout(() => {
				lastTime = Date.now();
				timer = null;
				result = fn.apply(this, args);
			}, remainingTime);
		}

		return result as R;
	};
}

/**
 * @name 等待
 * @param {number} [delay=1000] 时延
 */
async function waitFor(delay = 1000): Promise<boolean> {
	return await new Promise<boolean>(resolve => {
		setTimeout(() => {
			resolve(true);
		}, delay);
	});
}

export {
	asyncTo,
	debounce,
	throttle,
	waitFor
};