/** 类型工具 **/
import { arch, cpus, homedir, hostname, platform, release } from "node:os";

import { runCmd } from "./process";

/**
 * @name Node类型
 */
type SystemEnum = "windows" | "macos" | "linux";

type SystemType = Record<SystemEnum, RegExp>;

interface NodesType {
	arch: string
	cpus: number
	homedir: string
	hostname: string
	nodeVs: string
	npmVs: string
	system: SystemEnum | "unknow"
	systemVs: string
}

function nodeType(): NodesType {
	const testUa = (regexp: RegExp): boolean => regexp.test(platform().toLowerCase());
	/* eslint-disable sort-properties/sort-object-expression */
	const systemMap: SystemType = {
		windows: /win32/g,
		macos: /darwin/g,
		linux: /linux/g
	};
	/* eslint-enable */
	const system = (Object.keys(systemMap).find(v => testUa(systemMap[v as SystemEnum])) ?? "unknow") as SystemEnum | "unknow";
	return {
		arch: arch(),
		cpus: cpus().length,
		homedir: homedir(),
		hostname: hostname(),
		nodeVs: process.version.replace(/^v/g, ""),
		npmVs: runCmd("npm -v"),
		system,
		systemVs: release()
	};
}

export {
	nodeType
};